const toComponent = ([name, desc, details, tech]) => ({ name, desc, details, tech })

export const nodes = raw.map((n) => ({
  w: 170,
  h: 56,
  ...n,
  components: (n.components || []).map(toComponent),
}))

export const nodeById = Object.fromEntries(nodes.map((n) => [n.id, n]))

